std::vector<std::uint32_t> words(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);auto n=f.tellg();check(f&&n>0&&n%4==0,"owned fixture shader");std::vector<std::uint32_t> v(static_cast<std::size_t>(n)/4);f.seekg(0);f.read(reinterpret_cast<char*>(v.data()),n);return v;}
std::uint32_t memoryType(const VkPhysicalDeviceMemoryProperties&m,std::uint32_t bits,VkMemoryPropertyFlags flags){for(unsigned i=0;i<m.memoryTypeCount;++i)if((bits&(1u<<i))&&(m.memoryTypes[i].propertyFlags&flags)==flags)return i;throw std::runtime_error("fixture memory unavailable");}
