  VkDescriptorSetLayoutCreateInfo eli{};eli.sType=VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;ok(vkCreateDescriptorSetLayout(device,&eli,nullptr,&empty),"empty set0");VkDescriptorSetLayout sets[]={empty,pool.descriptorLayout()};VkPipelineLayoutCreateInfo li{};li.sType=VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;li.setLayoutCount=2;li.pSetLayouts=sets;ok(vkCreatePipelineLayout(device,&li,nullptr,&layout),"set1 compatible layout");
