int main(int argc,char**argv){try{check(argc==3,"vertex and fragment paths");GPU gpu(argv[1],argv[2]);std::array<std::uint8_t,16> pixels{{0,16,32,64,128,192,240,255,255,240,192,128,64,32,16,0}};FrameIdentity f{};f.binding[0]=11;f.descriptor={1,1,16,1};check(gpu.pool.upload(f,16,1,{pixels.data(),pixels.size()}),"real immutable upload");check(!gpu.pool.acquire(f),"real pending copy cannot bind");check(!gpu.pool.acquireScheduled(f),"real fresh image cannot be scheduled before initialization");gpu.pool.drainUploads(gpu.queue);Lease l{};auto end=std::chrono::steady_clock::now()+std::chrono::seconds(3);do{gpu.pool.reapCold();l=gpu.pool.acquire(f);if(l)break;std::this_thread::yield();}while(std::chrono::steady_clock::now()<end);check(bool(l),"real upload fence completed");gpu.sample(l,pixels);gpu.sample(l,pixels);gpu.pool.releaseRecorded(l);ok(vkQueueWaitIdle(gpu.queue),"fixture teardown-only queue wait");gpu.pool.reapCold();check(gpu.pool.statusCold().submitted==0&&gpu.pool.statusCold().recorded==0,"actual reused CB tail retirement");
 std::array<Lease,MaximumSlots> held{};for(unsigned i=0;i<MaximumSlots;++i){f.descriptor.sourceFrame=i+2;std::fill(pixels.begin(),pixels.end(),static_cast<std::uint8_t>(i*31));check(gpu.pool.upload(f,16,1,{pixels.data(),pixels.size()}),"real next immutable upload");gpu.pool.drainUploads(gpu.queue);end=std::chrono::steady_clock::now()+std::chrono::seconds(3);do{gpu.pool.reapCold();held[i]=gpu.pool.acquire(f);if(held[i])break;std::this_thread::yield();}while(std::chrono::steady_clock::now()<end);check(bool(held[i]),"real held slot ready");gpu.sample(held[i],pixels);}
 f.descriptor.sourceFrame=10;check(!gpu.pool.upload(f,16,1,{pixels.data(),pixels.size()}),"real eight held resources retain immutable images");for(const auto&x:held)gpu.pool.releaseRecorded(x);
 ok(vkQueueWaitIdle(gpu.queue),"fixture completes prior mask uses");gpu.pool.reapCold();
 std::fill(pixels.begin(),pixels.end(),231);check(gpu.pool.upload(f,16,1,{pixels.data(),pixels.size()}),"real same extent pending upload");
 check(!gpu.pool.acquire(f),"real strict acquire still waits for reap");auto scheduled=gpu.pool.acquireScheduled(f);check(bool(scheduled),"real initialized descriptor recordable before current copy submit");
 // Record first, then the ORIGINAL queue owner submits this copy immediately
 // before the actual draw. No CPU fence polling/reap occurs between them.
 gpu.sample(scheduled,pixels,true);gpu.pool.releaseRecorded(scheduled);
 ok(vkQueueWaitIdle(gpu.queue),"fixture scheduled teardown completion");gpu.pool.reapCold();
 auto strict=gpu.pool.acquire(f);check(bool(strict),"real strict acquire after scheduled upload reap");gpu.pool.releaseRecorded(strict);
 std::cout<<"{\"result\":\"PASS\",\"assertions\":"<<assertions<<",\"sampled_pixels\":176,\"optional_features\":false}\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
